<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,watch} from 'vue'
import {useRoute,onBeforeRouteLeave} from 'vue-router'
import {Puzzle,Plus,Upload,Play,History,Trash2} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import {canonical,type Document} from '../domain/local-contract'
import Sheet from '../components/Sheet.vue'
import {builtinPlugins} from './catalog'
import {validateInstalledPlugin,type InstalledPlugin,type PluginOverrides,type PluginScope,type PluginEditorDraft} from './contract'
import {installPlugin,parsePluginPackage,restorePluginVersion,commitPluginDocuments} from './runtime'
import {runPluginSandbox} from './sandbox'
const store=useLocal(),route=useRoute(),targetId=String(route.query.session||''),rows=ref<Document<InstalledPlugin>[]>([]),selected=ref<Document<InstalledPlugin>|null>(null),history=ref<Document<InstalledPlugin>[]>([]),error=ref(''),busy=ref(false),search=ref(''),source=ref(''),manifest=ref(''),editor=ref(false),preview=ref(''),override=ref<Document<PluginOverrides>|null>(null),mode=ref('inherit'),parameters=ref('{}'),targetTitle=ref('')
const control=new AbortController();let disposed=false,formEpoch=0,editorEpoch=0
const visible=computed(()=>rows.value.filter(row=>!row.value.deleted&&canonical(row.value.manifest).toLowerCase().includes(search.value.toLowerCase())))
const uninstalled=computed(()=>builtinPlugins.filter(plugin=>!rows.value.some(row=>row.id==='plugin:'+plugin.manifest.id&&!row.value.deleted)))
const scopeName:Record<PluginScope,string>={messages:'本会话的可见、选中消息',card:'当前角色设定',memory:'此伴侣已确认记忆',lorebook:'本会话世界书（按角色过滤）'}
async function load(){const vault=store.vault;if(!vault)return;const list=(await vault.list<InstalledPlugin>('settings')).filter(row=>row.value.assetType==='chat-plugin'),settings=targetId?await vault.read<PluginOverrides>('plugin-overrides:'+targetId):null,target=targetId?await vault.read<{title:string}>(targetId):null;if(disposed||store.vault!==vault)return;rows.value=list;override.value=settings;targetTitle.value=target?.value.title||''}
async function install(value:InstalledPlugin){const vault=store.vault;if(!vault||busy.value)return;busy.value=true;error.value='';try{await installPlugin(vault,value,control.signal);await load()}catch(e){if(!disposed)error.value=(e as Error).message}finally{busy.value=false}}
async function open(row:Document<InstalledPlugin>){const epoch=++formEpoch;selected.value=JSON.parse(canonical(row));history.value=[];mode.value=override.value?.value.entries[row.id]?.mode||'inherit';parameters.value=JSON.stringify(override.value?.value.entries[row.id]?.parameters||row.value.parameters||row.value.manifest.parameters,null,2);preview.value='';const vault=store.vault,versions:Document<InstalledPlugin>[]=[];if(vault)for(let revision=row.revision;revision>=Math.max(1,row.revision-9);revision--){const old=await vault.read<InstalledPlugin>(row.id,revision);if(disposed||epoch!==formEpoch)return;if(old)versions.push(old)}if(epoch===formEpoch)history.value=versions}
function closeForm(){formEpoch++;selected.value=null}
async function update(row:Document<InstalledPlugin>,value:InstalledPlugin){const vault=store.vault;if(!vault)return;validateInstalledPlugin(value,row.id);await commitPluginDocuments(vault,[{kind:'settings',id:row.id,expectedRevision:row.revision,value}],control.signal);await load()}
async function save(){const row=selected.value?JSON.parse(canonical(selected.value)) as Document<InstalledPlugin>:null,epoch=formEpoch,vault=store.vault;if(!row||!vault)return;try{const config=JSON.parse(parameters.value);if(targetId){const entries={...override.value?.value.entries,[row.id]:{mode:mode.value as 'inherit'|'on'|'off',version:row.value.manifest.version,parameters:config}},value:PluginOverrides={assetType:'plugin-overrides',targetId,targetKind:'session',entries};await commitPluginDocuments(vault,[{kind:'settings',id:'plugin-overrides:'+targetId,expectedRevision:override.value?.revision||0,value}],control.signal);await load()}else await update(row,{...row.value,parameters:config});if(!disposed&&epoch===formEpoch)closeForm()}catch(e){if(!disposed)error.value=(e as Error).message}}
async function remove(){const row=selected.value?JSON.parse(canonical(selected.value)) as Document<InstalledPlugin>:null,epoch=formEpoch;if(!row)return;try{await update(row,{...row.value,enabled:false,grants:[],deleted:true});if(!disposed&&epoch===formEpoch)closeForm()}catch(e){if(!disposed)error.value=(e as Error).message}}
async function restore(row:Document<InstalledPlugin>){const vault=store.vault,epoch=formEpoch;if(!vault)return;try{const restored=await restorePluginVersion(vault,row.id,row.revision,control.signal);await load();if(!disposed&&epoch===formEpoch)await open(restored)}catch(e){if(!disposed)error.value=(e as Error).message}}
function create(){editorEpoch++;if(manifest.value||source.value){editor.value=true;return}manifest.value=JSON.stringify({schema:'reader-plugin-v1',id:'my-plugin',name:'我的插件',version:'1.0.0',description:'',hooks:['onUserAction'],reads:[],writes:['suggestions'],modelCalls:0,budget:{steps:1,milliseconds:300,bytes:32000},parameters:{}},null,2);source.value="return {suggestions:[{title:'一句话',text:'这是一份可编辑的建议。',sourceIds:[]}]};";editor.value=true}
function edit(){if(!selected.value)return;editorEpoch++;manifest.value=JSON.stringify(selected.value.value.manifest,null,2);source.value=selected.value.value.source;editor.value=true}
async function savePackage(){const epoch=editorEpoch;try{const value=parsePluginPackage(JSON.stringify({manifest:JSON.parse(manifest.value),source:source.value}));await install(value);if(!disposed&&epoch===editorEpoch&&!error.value)editor.value=false}catch(e){error.value=(e as Error).message}}
async function importFile(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;try{if(file.size>256*1024)throw Error('侧载文件超过 256 KiB');const value=parsePluginPackage(await file.text());control.signal.throwIfAborted();await install(value)}catch(e){if(!disposed)error.value=(e as Error).message}(event.target as HTMLInputElement).value=''}
async function test(){const epoch=editorEpoch;try{const value=parsePluginPackage(JSON.stringify({manifest:JSON.parse(manifest.value),source:source.value})),result=await runPluginSandbox(value.source,{hook:'onUserAction',text:'演示文字',query:'preview',speaker:'演示角色',references:[]},value.manifest.parameters,value.manifest.budget.milliseconds,value.manifest.budget.bytes,control.signal);if(!disposed&&epoch===editorEpoch)preview.value=JSON.stringify(result,null,2)}catch(e){if(!disposed&&epoch===editorEpoch)preview.value=(e as Error).message}}
onMounted(()=>void Promise.all([load(),hydrateDraft()]).catch(e=>error.value=(e as Error).message));onUnmounted(()=>{disposed=true;control.abort();window.removeEventListener('beforeunload',unload)})
const draftId='settings:plugin-editor-draft',draftConflict='plugin-editor-conflict:'+crypto.randomUUID(),drafts=ref<Document<PluginEditorDraft>[]>([]),hydrating=ref(true)
let draftRevision=0,conflictRevision=0,draftWork=Promise.resolve(),durable=canonical(['',''])
async function hydrateDraft(){const vault=store.vault;if(!vault)return;const row=await vault.read<PluginEditorDraft>(draftId),copies=(await vault.list<PluginEditorDraft>('settings')).filter(row=>row.value.assetType==='plugin-editor-draft'&&row.value.conflict);if(disposed||store.vault!==vault)return;if(row){manifest.value=row.value.manifest;source.value=row.value.source;draftRevision=row.revision;durable=canonical([manifest.value,source.value])}drafts.value=copies;hydrating.value=false}
function persistDraft(){const vault=store.vault,values={manifest:manifest.value,source:source.value};if(!vault||hydrating.value)return draftWork;draftWork=draftWork.then(async()=>{if(!vault.unlocked||canonical([values.manifest,values.source])===durable)return;const value:PluginEditorDraft={assetType:'plugin-editor-draft',...values,conflict:false,createdAt:new Date().toISOString()};try{const receipt=(await commitPluginDocuments(vault,[{kind:'settings',id:draftId,expectedRevision:draftRevision,value}]))[0]!;draftRevision=receipt.revision}catch(e){if((e as {code?:string}).code!=='REVISION_CONFLICT')throw e;const receipt=(await commitPluginDocuments(vault,[{kind:'settings',id:draftConflict,expectedRevision:conflictRevision,value:{...value,conflict:true}}]))[0]!;conflictRevision=receipt.revision;if(!disposed)error.value='另一份插件草稿已保存为副本。'}durable=canonical([values.manifest,values.source])}).catch(e=>{if(!disposed)error.value=(e as Error).message});return draftWork}
async function useDraft(row:Document<PluginEditorDraft>){const head=await store.vault?.read(draftId);draftRevision=head?.revision||0;manifest.value=row.value.manifest;source.value=row.value.source;editor.value=true;await persistDraft()}
watch([manifest,source],()=>void persistDraft(),{flush:'sync'});onBeforeRouteLeave(async()=>{await persistDraft();if(store.vault&&durable!==canonical([manifest.value,source.value])){error.value='插件草稿没有保存成功，已留在当前页面。请重试保存后离开。';return false}})
function unload(event:BeforeUnloadEvent){if(store.vault&&!hydrating.value&&durable!==canonical([manifest.value,source.value])){event.preventDefault();event.returnValue=''}}
window.addEventListener('beforeunload',unload)
</script>
<template><section class="final-plugins"><div class="final-page-heading"><div><span class="final-eyebrow">WORKSPACE</span><h1><Puzzle :size="32"/>插件</h1><p v-if="targetTitle" class="final-subtle">{{targetTitle}}</p></div><div class="final-grid-actions"><label class="final-file-button"><Upload :size="17"/>侧载<input type="file" accept="application/json,.json" aria-label="侧载插件文件" @change="importFile"></label><button :disabled="hydrating" @click="create"><Plus :size="17"/>新建</button></div></div><p v-if="error" class="final-error" role="alert">{{error}}</p><input v-model="search" aria-label="搜索插件" type="search" placeholder="搜索插件"><details v-if="drafts.length"><summary>另存的插件草稿 · {{drafts.length}}</summary><button v-for="draft in drafts" :key="draft.id" @click="useDraft(draft)">{{new Date(draft.updatedAt).toLocaleString()}}</button></details><div class="plugin-grid"><button v-for="row in visible" :key="row.id" class="plugin-card" @click="open(row)"><span class="plugin-icon"><Puzzle :size="22"/></span><strong>{{row.value.manifest.name}}</strong><small>{{row.value.manifest.description}}</small><div><span>{{row.value.manifest.version}}</span><span>{{targetId?(override?.value.entries[row.id]?.mode==='off'?'关闭':override?.value.entries[row.id]?.mode==='on'?(override.value.entries[row.id]?.version===row.value.manifest.version?'会话开启':'待重新授权'):row.value.enabled?'继承 · 开启':'继承 · 关闭'):row.value.enabled?'已启用':'未启用'}}</span></div></button></div><template v-if="uninstalled.length"><h2>内置插件</h2><div class="plugin-grid"><article v-for="value in uninstalled" :key="value.manifest.id" class="plugin-card"><span class="plugin-icon"><Puzzle :size="22"/></span><strong>{{value.manifest.name}}</strong><small>{{value.manifest.description}}</small><button :disabled="busy" @click="install(value)">安装</button></article></div></template>
<Sheet v-if="selected" :title="selected.value.manifest.name" @close="closeForm"><form class="plugin-form" @submit.prevent="save"><label v-if="!targetId" class="final-check"><input v-model="selected.value.enabled" type="checkbox">全局启用</label><label v-else>本会话<select v-model="mode"><option value="inherit">继承全局</option><option value="on">开启</option><option value="off">关闭</option></select></label><fieldset><legend>允许读取</legend><label v-for="scope in selected.value.manifest.reads" :key="scope" class="final-check"><input v-model="selected.value.grants" type="checkbox" :value="scope" :disabled="!!targetId">{{scopeName[scope]}}</label></fieldset><details><summary>能力与执行上限</summary><p>{{selected.value.manifest.hooks.join(' · ')}}</p><p>{{selected.value.manifest.budget.steps}} 步 · {{selected.value.manifest.budget.milliseconds}} ms · 0 次模型调用</p><p>无网络、文件和密钥访问。</p></details><label>参数<textarea v-model="parameters" rows="5" aria-label="插件参数"></textarea></label><button class="final-primary">保存{{targetId?'会话设置':'权限'}}</button><button v-if="!selected.value.builtin" type="button" @click="edit">编辑脚本</button><details><summary><History :size="16"/>历史版本</summary><button v-for="row in history" :key="row.revision" type="button" :disabled="row.revision===selected.revision" @click="restore(row)">{{row.value.manifest.version}} · {{new Date(row.updatedAt).toLocaleString()}} · 回退为新版本</button></details><button type="button" @click="remove"><Trash2 :size="16"/>删除插件</button></form></Sheet>
<Sheet v-if="editor" title="插件编辑器" @close="editor=false;editorEpoch++"><form class="plugin-form" @submit.prevent="savePackage"><label>Manifest<textarea v-model="manifest" rows="16" aria-label="插件 manifest"></textarea></label><label>Worker 脚本<textarea v-model="source" rows="10" aria-label="插件脚本"></textarea></label><button type="button" @click="test"><Play :size="16"/>隔离预览</button><pre v-if="preview">{{preview}}</pre><button class="final-primary" :disabled="busy">保存新版本</button></form></Sheet>
</section></template>
<style scoped>.final-plugins{display:grid;gap:24px}.final-plugins h1{display:flex;gap:12px;align-items:center}.plugin-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.plugin-card{display:flex;flex-direction:column;gap:14px;align-items:flex-start;text-align:left;padding:24px;border:1px solid var(--edge);border-radius:16px;background:var(--paper);color:var(--ink);min-width:0}.plugin-card strong{font-size:19px}.plugin-card small{color:var(--quiet);line-height:1.6}.plugin-card>div{display:flex;justify-content:space-between;width:100%;font-size:12px;color:var(--quiet)}.plugin-icon{display:grid;place-items:center;width:48px;height:48px;background:var(--wash);color:var(--accent);border-radius:14px}.plugin-form{display:grid;gap:20px}.plugin-form label{display:grid;gap:8px}.plugin-form textarea{font:13px/1.6 monospace}.plugin-form textarea,.plugin-form select,.final-plugins>input{max-width:100%;width:100%;padding:12px;border:1px solid var(--edge);border-radius:10px;background:var(--paper);color:var(--ink)}.plugin-form pre{overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}.plugin-form details>button{display:block;margin:10px 0}@media(max-width:1000px){.plugin-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:600px){.plugin-grid{grid-template-columns:1fr}}</style>
